import React, { useRef, useMemo, useCallback } from "react";
import { AgGridReact } from "ag-grid-react";
import type { ColDef, ColGroupDef, GridReadyEvent } from "ag-grid-community";
import "ag-grid-community/styles/ag-grid.css";
import "ag-grid-community/styles/ag-theme-quartz.css";
import { Download, Search, RefreshCw, Layers } from "lucide-react";
import { BountyRow } from "../types";
import {
  StatusCellRenderer,
  BatchIdCellRenderer,
  RfpIdCellRenderer,
  LatencyCellRenderer
} from "./CellRenderers";

interface BountyGridProps {
  rowData: BountyRow[];
  onRefresh?: () => void;
}

export const BountyGrid: React.FC<BountyGridProps> = ({ rowData, onRefresh }) => {
  const gridRef = useRef<AgGridReact<BountyRow>>(null);

  // Quick Filter text search
  const onFilterTextBoxChanged = useCallback(() => {
    const input = document.getElementById("filter-text-box") as HTMLInputElement;
    gridRef.current?.api.setGridOption("quickFilterText", input.value);
  }, []);

  // Export to CSV
  const onExportCsv = useCallback(() => {
    gridRef.current?.api.exportDataAsCsv({
      fileName: `bounty_settlements_${new Date().toISOString().slice(0, 10)}.csv`
    });
  }, []);

  // Aggregation footer calculations (pinnedBottomRowData)
  const pinnedBottomRowData = useMemo(() => {
    if (!rowData || rowData.length === 0) return [];

    const totalVolume = rowData.reduce((acc, row) => acc + (row.amountPaidUsd || 0), 0);
    const validLatencies = rowData.filter((r) => r.latencyMs > 0);
    const avgLatency = validLatencies.length > 0
      ? Math.round(validLatencies.reduce((acc, r) => acc + r.latencyMs, 0) / validLatencies.length)
      : 0;

    return [
      {
        id: "summary_footer",
        time: "SUMMARY",
        rfpId: `Total Jobs: ${rowData.length}`,
        capability: "—",
        sellerNode: "All Nodes Active",
        status: "SETTLED" as const,
        bidUsd: rowData.reduce((acc, r) => acc + (r.bidUsd || 0), 0),
        amountPaidUsd: totalVolume,
        paypalBatchId: "—",
        latencyMs: avgLatency
      }
    ];
  }, [rowData]);

  // Column definitions with Column Grouping for Financials
  const columnDefs = useMemo<(ColDef<BountyRow> | ColGroupDef<BountyRow>)[]>(() => [
    {
      headerName: "Time",
      field: "time",
      sortable: true,
      filter: "agTextColumnFilter",
      floatingFilter: true,
      width: 105,
      checkboxSelection: (params) => !params.node.isRowPinned(),
      headerCheckboxSelection: true,
      cellClass: "font-mono text-xs text-slate-300"
    },
    {
      headerName: "RFP ID",
      field: "rfpId",
      sortable: true,
      filter: "agTextColumnFilter",
      floatingFilter: true,
      cellRenderer: RfpIdCellRenderer,
      width: 145
    },
    {
      headerName: "Capability",
      field: "capability",
      sortable: true,
      filter: "agTextColumnFilter",
      floatingFilter: true,
      width: 160,
      cellRenderer: (params: any) => (
        <span className="font-mono text-xs text-sky-400 font-medium">
          {params.value}
        </span>
      )
    },
    {
      headerName: "Seller Node",
      field: "sellerNode",
      sortable: true,
      filter: "agTextColumnFilter",
      floatingFilter: true,
      width: 220,
      cellRenderer: (params: any) => (
        <span className="font-mono text-xs text-slate-300">
          {params.value}
        </span>
      )
    },
    {
      headerName: "Status",
      field: "status",
      sortable: true,
      filter: "agTextColumnFilter",
      floatingFilter: true,
      cellRenderer: StatusCellRenderer,
      width: 140
    },
    // Column Group: Financial Settlement (PayPal)
    {
      headerName: "Financial Settlement (PayPal Rails)",
      headerClass: "bg-slate-800/80 text-yellow-400 font-semibold border-b border-yellow-500/30",
      children: [
        {
          headerName: "Bid ($)",
          field: "bidUsd",
          sortable: true,
          filter: "agNumberColumnFilter",
          floatingFilter: true,
          width: 105,
          valueFormatter: (params) =>
            typeof params.value === "number" ? `$${params.value.toFixed(2)}` : params.value,
          cellClass: "font-mono text-xs text-slate-200 tabular-nums font-semibold"
        },
        {
          headerName: "Amount Paid ($)",
          field: "amountPaidUsd",
          sortable: true,
          filter: "agNumberColumnFilter",
          floatingFilter: true,
          width: 135,
          valueFormatter: (params) =>
            typeof params.value === "number" ? `$${params.value.toFixed(2)}` : params.value,
          cellClass: "font-mono text-xs text-emerald-400 tabular-nums font-bold"
        },
        {
          headerName: "PayPal Batch ID",
          field: "paypalBatchId",
          sortable: true,
          filter: "agTextColumnFilter",
          floatingFilter: true,
          cellRenderer: BatchIdCellRenderer,
          width: 175
        }
      ]
    },
    {
      headerName: "Latency (ms)",
      field: "latencyMs",
      sortable: true,
      filter: "agNumberColumnFilter",
      floatingFilter: true,
      cellRenderer: LatencyCellRenderer,
      width: 160
    }
  ], []);

  const defaultColDef = useMemo<ColDef>(() => ({
    resizable: true,
    sortable: true,
    filter: true
  }), []);

  const onGridReady = useCallback((params: GridReadyEvent) => {
    params.api.sizeColumnsToFit();
  }, []);

  return (
    <div className="bg-slate-900/90 border border-slate-800 rounded-xl p-4 shadow-xl backdrop-blur-sm flex flex-col">
      {/* Grid Action Toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-3 mb-4 pb-3 border-b border-slate-800/80">
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2">
            <Layers className="w-5 h-5 text-sky-400" />
            <h3 className="text-base font-bold text-white tracking-wide">
              Real-Time Settlement Ledger
            </h3>
          </div>
          <span className="text-xs px-2.5 py-0.5 rounded-full bg-slate-800 text-slate-400 border border-slate-700 font-mono">
            {rowData.length} entries
          </span>
        </div>

        <div className="flex items-center gap-2.5">
          {/* Quick Filter */}
          <div className="relative">
            <Search className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
            <input
              type="text"
              id="filter-text-box"
              placeholder="Filter transactions..."
              onInput={onFilterTextBoxChanged}
              className="bg-slate-950 border border-slate-800 rounded-lg pl-8 pr-3 py-1.5 text-xs text-slate-200 placeholder-slate-500 focus:outline-none focus:border-sky-500 w-44 sm:w-56 transition-colors"
            />
          </div>

          {/* Refresh Button */}
          {onRefresh && (
            <button
              onClick={onRefresh}
              title="Refresh ledger data"
              className="p-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 border border-slate-700 text-slate-300 hover:text-white transition-colors cursor-pointer"
            >
              <RefreshCw className="w-4 h-4" />
            </button>
          )}

          {/* Export CSV Button */}
          <button
            onClick={onExportCsv}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-sky-600 hover:bg-sky-500 text-white text-xs font-semibold shadow-md transition-colors cursor-pointer"
          >
            <Download className="w-3.5 h-3.5" />
            Export CSV
          </button>
        </div>
      </div>

      {/* The AG Grid Canvas */}
      <div
        className="ag-theme-quartz-dark w-full rounded-lg overflow-hidden border border-slate-800"
        style={{ height: "480px" }}
      >
        <AgGridReact<BountyRow>
          ref={gridRef}
          theme="legacy"
          rowData={rowData}
          columnDefs={columnDefs}
          defaultColDef={defaultColDef}
          rowSelection="multiple"
          suppressRowClickSelection={true}
          pinnedBottomRowData={pinnedBottomRowData}
          onGridReady={onGridReady}
          animateRows={true}
          pagination={true}
          paginationPageSize={10}
          paginationPageSizeSelector={[10, 20, 50]}
        />
      </div>

      {/* Grid Features Sponsor Note */}
      <div className="flex flex-wrap items-center justify-between mt-3 text-[11px] text-slate-500 font-mono">
        <div>
          <span>Features: Column Filtering · Floating Filters · Grouped Financials · Monospace Copy · CSV Export · Pinned Aggregations</span>
        </div>
        <div className="text-yellow-400 font-medium">
          AG Grid Community v33 (Full Open-Source Compliance)
        </div>
      </div>
    </div>
  );
};

import React, { useState } from "react";
import { Sliders, CheckCircle2, ShieldCheck, Terminal, FileText, Globe, Network } from "lucide-react";

interface Capability {
  id: string;
  name: string;
  desc: string;
  floorPrice: string;
  enabled: boolean;
  icon: any;
}

export const CapabilityPanel: React.FC = () => {
  const [capabilities, setCapabilities] = useState<Capability[]>([
    {
      id: "python_code",
      name: "python_code",
      desc: "Subprocess execution with AST syntax & unit test verification",
      floorPrice: "$0.25",
      enabled: true,
      icon: Terminal
    },
    {
      id: "ocr",
      name: "ocr",
      desc: "Tesseract v5.4.0 neural net OCR on image bytes",
      floorPrice: "$0.20",
      enabled: true,
      icon: FileText
    },
    {
      id: "web_scrape",
      name: "web_scrape",
      desc: "httpx client + BeautifulSoup HTML sanitization",
      floorPrice: "$0.05",
      enabled: true,
      icon: Globe
    },
    {
      id: "residential_scrape",
      name: "residential_scrape",
      desc: "Residential proxy routing with Cloudflare Turnstile clearance",
      floorPrice: "$0.05",
      enabled: true,
      icon: Network
    }
  ]);

  const [broadcastStatus, setBroadcastStatus] = useState<string | null>(null);

  const toggleCapability = async (id: string) => {
    const cap = capabilities.find((c) => c.id === id);
    if (!cap) return;
    const nextState = !cap.enabled;

    setCapabilities((prev) =>
      prev.map((c) => (c.id === id ? { ...c, enabled: nextState } : c))
    );

    try {
      await fetch("http://localhost:4000/api/capabilities/toggle", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ capability: id, enabled: nextState })
      });
      setBroadcastStatus(`Broadcasted ${id} ${nextState ? "ENABLED" : "DISABLED"} to worker mesh`);
      setTimeout(() => setBroadcastStatus(null), 3000);
    } catch {
      // Local fallback
      setBroadcastStatus(`Updated ${id} locally`);
      setTimeout(() => setBroadcastStatus(null), 2500);
    }
  };

  return (
    <div className="bg-slate-900/90 border border-slate-800 rounded-xl p-4 mb-6 shadow-lg backdrop-blur-sm">
      <div className="flex flex-wrap items-center justify-between gap-2 mb-3">
        <div className="flex items-center gap-2">
          <Sliders className="w-4 h-4 text-sky-400" />
          <h4 className="text-sm font-semibold text-white tracking-wide">
            Live Worker Capability Mesh & Floor Prices
          </h4>
          <span className="text-xs px-2 py-0.5 rounded bg-sky-950/80 text-sky-400 border border-sky-800/40">
            Real-Time Broadcast
          </span>
        </div>
        {broadcastStatus && (
          <span className="text-xs text-emerald-400 flex items-center gap-1 animate-fade-in font-mono">
            <CheckCircle2 className="w-3.5 h-3.5" />
            {broadcastStatus}
          </span>
        )}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {capabilities.map((cap) => {
          const Icon = cap.icon;
          return (
            <div
              key={cap.id}
              onClick={() => toggleCapability(cap.id)}
              className={`p-3 rounded-lg border transition-all cursor-pointer flex flex-col justify-between select-none ${
                cap.enabled
                  ? "bg-slate-800/60 border-slate-700/80 hover:border-sky-500/50"
                  : "bg-slate-950/40 border-slate-900 opacity-60 hover:opacity-80"
              }`}
            >
              <div>
                <div className="flex items-center justify-between mb-1.5">
                  <div className="flex items-center gap-1.5">
                    <Icon className={`w-4 h-4 ${cap.enabled ? "text-sky-400" : "text-slate-500"}`} />
                    <span className="text-xs font-mono font-semibold text-slate-200">
                      {cap.name}
                    </span>
                  </div>
                  {/* Switch */}
                  <div
                    className={`w-8 h-4 rounded-full transition-colors relative flex items-center px-0.5 ${
                      cap.enabled ? "bg-sky-500" : "bg-slate-700"
                    }`}
                  >
                    <div
                      className={`w-3 h-3 rounded-full bg-white transition-transform ${
                        cap.enabled ? "translate-x-4" : "translate-x-0"
                      }`}
                    />
                  </div>
                </div>
                <p className="text-[11px] text-slate-400 line-clamp-2 leading-relaxed">
                  {cap.desc}
                </p>
              </div>

              <div className="flex items-center justify-between mt-3 pt-2 border-t border-slate-800/60">
                <span className="text-[10px] uppercase text-slate-500 font-semibold tracking-wider">
                  Floor Floor
                </span>
                <span className="text-xs font-mono font-bold text-amber-400">
                  {cap.floorPrice}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState } from "react";
import type { ICellRendererParams } from "ag-grid-community";
import { Copy, Check, Clock, Loader2, CheckCircle2, XCircle, CreditCard } from "lucide-react";

export const StatusCellRenderer: React.FC<ICellRendererParams> = (params) => {
  const status = (params.value || "").toUpperCase();

  switch (status) {
    case "SETTLED":
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-950/80 text-emerald-400 border border-emerald-500/30">
          <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
          <CreditCard className="w-3 h-3" />
          SETTLED
        </span>
      );
    case "VERIFIED":
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-semibold bg-cyan-950/80 text-cyan-400 border border-cyan-500/30">
          <CheckCircle2 className="w-3 h-3" />
          VERIFIED
        </span>
      );
    case "EXECUTING":
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-semibold bg-amber-950/80 text-amber-400 border border-amber-500/30">
          <Loader2 className="w-3 h-3 animate-spin" />
          EXECUTING
        </span>
      );
    case "CLAIMED":
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-semibold bg-blue-950/80 text-blue-400 border border-blue-500/30">
          <Clock className="w-3 h-3" />
          CLAIMED
        </span>
      );
    case "FAILED":
      return (
        <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-semibold bg-rose-950/80 text-rose-400 border border-rose-500/30">
          <XCircle className="w-3 h-3" />
          FAILED
        </span>
      );
    default:
      return <span className="text-xs text-slate-400">{params.value || "—"}</span>;
  }
};

export const BatchIdCellRenderer: React.FC<ICellRendererParams> = (params) => {
  const [copied, setCopied] = useState(false);
  const rawId = params.value || "";

  if (!rawId || rawId === "—") {
    return <span className="text-slate-500 text-xs">—</span>;
  }

  const handleCopy = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(rawId);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  return (
    <button
      onClick={handleCopy}
      title="Click to copy full PayPal Batch ID"
      className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-slate-800/80 hover:bg-slate-700 text-sky-400 font-mono text-xs border border-slate-700/60 transition-colors group cursor-pointer"
    >
      <span>{rawId.length > 14 ? `${rawId.slice(0, 14)}...` : rawId}</span>
      {copied ? (
        <Check className="w-3 h-3 text-emerald-400" />
      ) : (
        <Copy className="w-3 h-3 text-slate-400 group-hover:text-sky-300 opacity-60 group-hover:opacity-100" />
      )}
    </button>
  );
};

export const RfpIdCellRenderer: React.FC<ICellRendererParams> = (params) => {
  const [copied, setCopied] = useState(false);
  const rawId = params.value || "";

  if (!rawId) return <span className="text-slate-500 text-xs">—</span>;

  const handleCopy = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(rawId);
    setCopied(true);
    setTimeout(() => setCopied(false), 1500);
  };

  const truncated = rawId.length > 12 ? `${rawId.slice(0, 10)}...` : rawId;

  return (
    <button
      onClick={handleCopy}
      title={`Click to copy: ${rawId}`}
      className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-slate-900/60 hover:bg-slate-800 text-slate-300 font-mono text-xs border border-slate-800 hover:border-slate-700 transition-colors group cursor-pointer"
    >
      <span>{truncated}</span>
      {copied ? (
        <Check className="w-3 h-3 text-emerald-400" />
      ) : (
        <Copy className="w-3 h-3 text-slate-500 group-hover:text-slate-300" />
      )}
    </button>
  );
};

export const LatencyCellRenderer: React.FC<ICellRendererParams> = (params) => {
  const ms = Number(params.value || 0);
  if (!ms) return <span className="text-slate-500 text-xs">—</span>;

  // Max scale 4000ms
  const pct = Math.min(100, Math.max(5, (ms / 4000) * 100));

  let barColor = "bg-emerald-500";
  if (ms > 2500) barColor = "bg-rose-500";
  else if (ms > 1500) barColor = "bg-amber-500";

  return (
    <div className="flex items-center gap-2 w-full h-full">
      <div className="w-16 bg-slate-800/80 rounded-full h-1.5 overflow-hidden">
        <div
          className={`h-full ${barColor} rounded-full transition-all duration-300`}
          style={{ width: `${pct}%` }}
        />
      </div>
      <span className="text-xs font-mono text-slate-300 tabular-nums">
        {ms}ms
      </span>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from "react";
import { Zap, ShieldCheck, CreditCard, Award, ExternalLink, Wifi } from "lucide-react";
